    Simulates the sequence and checks if any term is divisible by k for all k in k_values.
    Returns True if Condition 1 holds for the given moduli up to N terms, False otherwise.
    """
    a_n = 2024

    # Check initial state
    if any(a_n % k == 0 for k in k_values):
        return True

    # b_n calculation
    def f(x):
        # Ensure we handle large numbers if they occur, but focus on modulo arithmetic for divisibility check
        return A * x**2 + B * x + 10000

    b_n = f(a_n)

    if any(b_n % k == 0 for k in k_values):
        return True

    # a_{n+1} calculation
    def g(x):
        return C * x**2 + D * x + 2026

    current_a = a_n
    current_b = b_n

    for _ in range(1, N):
        # Calculate next term b_n = f(a_n)
        # We only care about divisibility, so we can potentially use modulo, 
        # but since we need the exact value for the next step, we calculate full value.
        current_b = f(current_a)
        if any(current_b % k == 0 for k in k_values):
            return True

        # Calculate next term a_{n+1} = g(b_n)
        current_a = g(current_b)
